  var APP = "app";
  var SLEEP = "HKCategoryTypeIdentifierSleepAnalysis";
  var STAGE_MAP = { light: "core", deep: "deep", rem: "rem", awake: "awake", sleeping: "unspecified" };   // importers/ow.py
  var DEVICE_PRIORITY = { watch: 0, band: 0, ring: 0, phone: 1 };

